const html = await (await fetch("/")).text();
const mock = `<script>
window.__mode = "success";
class MockSR {
  start() {
    const mode = window.__mode;
    setTimeout(() => this.onstart && this.onstart(), 10);
    if (mode === "success") setTimeout(() => this.onresult && this.onresult({ results: [[{ transcript: "Which hubs face the most flood risk" }]] }), 30);
    else setTimeout(() => this.onerror && this.onerror({ error: mode }), 30);
    setTimeout(() => this.onend && this.onend(), 50);
  }
  stop() {} abort() {}
}
window.SpeechRecognition = undefined; window.webkitSpeechRecognition = MockSR;
<\/script>`;
async function run(mode) {
  const f = document.createElement("iframe");
  f.style.cssText = "width:800px;height:400px";
  f.srcdoc = html.replace("<script>", mock.replace('"success"', JSON.stringify(mode)) + "<script>");
  document.body.appendChild(f);
  await new Promise((r) => f.onload = r);
  await new Promise((r) => setTimeout(r, 200));
  const d = f.contentDocument;
  d.getElementById("mic").click();
  await new Promise((r) => setTimeout(r, 200));
  const res = { input: d.getElementById("input").value, status: d.getElementById("status").textContent,
    micHidden: d.getElementById("mic").hidden, sentAutomatically: !!d.querySelector(".msg-user") };
  f.remove();
  return res;
}
({ success: await run("success"), network: await run("network"), noSpeech: await run("no-speech") })

