async function probe(url) {
  const f = document.createElement("iframe");
  f.style.cssText = "position:fixed;left:0;top:0;width:1000px;height:700px;opacity:0";
  f.src = url; document.body.appendChild(f);
  await new Promise((r) => f.onload = r); await new Promise((r) => setTimeout(r, 300));
  const d = f.contentDocument, w = f.contentWindow, m = d.getElementById("mic");
  const r = m.getBoundingClientRect(), cs = w.getComputedStyle(m);
  const top = d.elementFromPoint(r.left + r.width / 2, r.top + r.height / 2);
  const out = { url, hiddenProp: m.hidden, display: cs.display, visibility: cs.visibility,
    pointerEvents: cs.pointerEvents, disabled: m.disabled, rect: [Math.round(r.left), Math.round(r.top), Math.round(r.width), Math.round(r.height)],
    elementOnTop: top ? (top.id || top.tagName) : null };
  f.remove(); return out;
}
[await probe("/"), await probe("/?voice=1")]

