async function probe(url) {
  const f = document.createElement("iframe");
  f.style.cssText = "position:fixed;left:0;top:0;width:1000px;height:700px;opacity:0";
  f.src = url; document.body.appendChild(f);
  await new Promise((r) => f.onload = r); await new Promise((r) => setTimeout(r, 400));
  const d = f.contentDocument, w = f.contentWindow, m = d.getElementById("mic");
  const r = m.getBoundingClientRect();
  const top = d.elementFromPoint(r.left + r.width / 2, r.top + r.height / 2);
  m.click(); await new Promise((r) => setTimeout(r, 300));
  const out = { url, micVisible: w.getComputedStyle(m).display !== "none", micOnTop: top === m || m.contains(top),
    listener: m.dataset.listener, statusAfterClick: d.getElementById("status").textContent,
    logBoxVisible: !d.getElementById("voicelog").hidden };
  f.remove(); return out;
}
